#include <lightoverleaf/session/adapters/ksqlitesessionstore.h>
#include <sqlite3.h>
#include <mutex>
namespace lightoverleaf::session {class KStore final:public IKSessionStore{public:explicit KStore(sqlite3*d):m_db(d){}~KStore()override{sqlite3_close(m_db);}KResult<std::optional<KStoredSession>>load()const override{std::scoped_lock l(m);sqlite3_stmt*s=nullptr;if(sqlite3_prepare_v2(m_db,"SELECT workspace_root,open_files,active_file,sidebar_width,preview_open FROM session_state WHERE id=1",-1,&s,nullptr)!=SQLITE_OK)return err();struct F{sqlite3_stmt*s;~F(){sqlite3_finalize(s);}}f{s};if(sqlite3_step(s)!=SQLITE_ROW)return std::optional<KStoredSession>{};return std::optional<KStoredSession>{KStoredSession{reinterpret_cast<const char*>(sqlite3_column_text(s,0)),reinterpret_cast<const char*>(sqlite3_column_text(s,1)),reinterpret_cast<const char*>(sqlite3_column_text(s,2)),static_cast<unsigned>(sqlite3_column_int(s,3)),sqlite3_column_int(s,4)!=0}};}
KResult<bool>save(const KStoredSession&v)override{std::scoped_lock l(m);sqlite3_exec(m_db,"BEGIN IMMEDIATE",nullptr,nullptr,nullptr);sqlite3_stmt*s=nullptr;const char*q="INSERT INTO session_state VALUES(1,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET workspace_root=excluded.workspace_root,open_files=excluded.open_files,active_file=excluded.active_file,sidebar_width=excluded.sidebar_width,preview_open=excluded.preview_open";if(sqlite3_prepare_v2(m_db,q,-1,&s,nullptr)!=SQLITE_OK){sqlite3_exec(m_db,"ROLLBACK",nullptr,nullptr,nullptr);return err();}sqlite3_bind_text(s,1,v.m_workspaceRoot.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,v.m_openFiles.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,v.m_activeFile.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_int(s,4,v.m_sidebarWidth);sqlite3_bind_int(s,5,v.m_previewOpen);bool ok=sqlite3_step(s)==SQLITE_DONE;sqlite3_finalize(s);if(ok){sqlite3_stmt*h=nullptr;sqlite3_prepare_v2(m_db,"INSERT INTO workspace_history(root,last_opened) VALUES(?,unixepoch()) ON CONFLICT(root) DO UPDATE SET last_opened=excluded.last_opened",-1,&h,nullptr);sqlite3_bind_text(h,1,v.m_workspaceRoot.c_str(),-1,SQLITE_TRANSIENT);ok=sqlite3_step(h)==SQLITE_DONE;sqlite3_finalize(h);}sqlite3_exec(m_db,ok?"COMMIT":"ROLLBACK",nullptr,nullptr,nullptr);return ok?KResult<bool>{true}:KResult<bool>{err()};}
KResult<std::vector<std::string>>history()const override{std::scoped_lock l(m);sqlite3_stmt*s=nullptr;if(sqlite3_prepare_v2(m_db,"SELECT root FROM workspace_history ORDER BY last_opened DESC LIMIT 20",-1,&s,nullptr)!=SQLITE_OK)return err();struct F{sqlite3_stmt*s;~F(){sqlite3_finalize(s);}}f{s};std::vector<std::string>r;while(sqlite3_step(s)==SQLITE_ROW)r.emplace_back(reinterpret_cast<const char*>(sqlite3_column_text(s,0)));return r;}private:KError err()const{return{KErrorCode::Unavailable,"session.storageFailure",true};}sqlite3*m_db;mutable std::mutex m;};
KResult<std::shared_ptr<IKSessionStore>>createSqliteSessionStore(const std::string&p){sqlite3*d=nullptr;if(sqlite3_open_v2(p.c_str(),&d,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE|SQLITE_OPEN_FULLMUTEX,nullptr)!=SQLITE_OK){if(d)sqlite3_close(d);return KError{KErrorCode::Unavailable,"session.storageFailure",true};}const char*ddl="CREATE TABLE IF NOT EXISTS session_state(id INTEGER PRIMARY KEY,workspace_root TEXT NOT NULL,open_files TEXT NOT NULL,active_file TEXT NOT NULL,sidebar_width INTEGER NOT NULL,preview_open INTEGER NOT NULL);CREATE TABLE IF NOT EXISTS workspace_history(root TEXT PRIMARY KEY,last_opened INTEGER NOT NULL)";if(sqlite3_exec(d,ddl,nullptr,nullptr,nullptr)!=SQLITE_OK){sqlite3_close(d);return KError{KErrorCode::Unavailable,"session.storageFailure",true};}return std::shared_ptr<IKSessionStore>(std::make_shared<KStore>(d));}}
